(7740105, 1276472, 50695, '<td valign="top">B/W + Texture does not equal Art. Big bright and glowy green is just as much Art. If you want to make it Art give him a hat or make him decide between his health and his livelihood or reassemble him into a country cottage. Art is a verb! Or is God a verb? Is Art God??</td>', 'B/W + Texture does not equal Art. Big bright and glowy green is just as much Art. If you want to make it Art give him a hat or make him decide between his health and his livelihood or reassemble him into a country cottage. Art is a verb! Or is God a verb? Is Art God??', '2023-03-14 15:10:04.000000', NULL, 1),
(7740121, 1276472, 124815, '<td valign="top">Why would horror film makers create robots and aliens when they can easily enlarge insects like this one. Terrifying! A great photo.</td>', 'Why would horror film makers create robots and aliens when they can easily enlarge insects like this one. Terrifying! A great photo.', '2023-03-14 18:11:36.000000', NULL, 1),
